/* Role-specific monitoring. Cross-office records are read-only projections from the server. */
let roleDashPeriod=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Makassar',year:'numeric',month:'2-digit'}).format(new Date()),roleDashOffice='',roleDashOwner='',roleDashQueue='',roleDashContext='';
const roleDashCache=new Map();
function rdCall(fn,...args){return E(fn+'('+args.map(x=>JSON.stringify(x)).join(',')+')')}
function rdContext(){const key=(authUser?.id||'')+'|'+(authUser?.role||'')+'|'+activeBranch;if(key!==roleDashContext){roleDashContext=key;roleDashOffice='';roleDashOwner='';roleDashQueue='';}return key}
function rdKey(){return rdContext()+'|'+roleDashPeriod+'|'+roleDashOffice+'|'+roleDashOwner+'|'+serverRevision}
function rdData(){return roleDashCache.get(rdKey())?.data}
async function rdLoad(force=false){if(!authUser||!activeBranch||choosingBranch||journey)return;const key=rdKey(),old=roleDashCache.get(key);if(old&&!force)return;roleDashCache.set(key,{loading:true,data:old?.data});try{const data=await api('dashboard?period='+encodeURIComponent(roleDashPeriod)+'&office='+encodeURIComponent(roleDashOffice)+'&owner='+encodeURIComponent(roleDashOwner));roleDashCache.set(key,{data});}catch(e){roleDashCache.set(key,{error:e.message});}finally{if(roleDashCache.size>16)for(const k of [...roleDashCache.keys()].slice(0,-12))roleDashCache.delete(k);if(key===rdKey()&&['Monitoring','Home'].includes(view))renderContent();}}
function rdFilter(kind,value){if(kind==='period')roleDashPeriod=value;if(kind==='office'){roleDashOffice=value;roleDashOwner='';}if(kind==='owner')roleDashOwner=value;roleDashQueue='';renderContent()}
function rdQueue(key){roleDashQueue=key;renderContent()}
function rdReset(){roleDashOffice='';roleDashOwner='';roleDashQueue='';renderContent()}
function rdMoney(n){return typeof dashboardCompactMoney==='function'?dashboardCompactMoney(n):rup(n)}
function rdGo(route){if(['Member','Pengaturan'].includes(route)&&authUser?.role==='Superadmin'&&activeBranch!==BPD_BRANCH_NAMES[0]){toast('Pilih HQ Renon untuk mengelola '+route+'.');return openBranchSelection();}go(route)}
function rdModal(title,body){document.querySelector('#modal')?.close();modal(E(title),body,()=>false);const form=document.querySelector('#form');form?.querySelector(':scope > .actions')?.remove();if(form)form.onsubmit=e=>e.preventDefault();}
function rdOpen(kind,id){const d=rdData(),x=Object.values(d?.records||{}).flat().find(x=>x.id===id&&x.kind===kind);if(!x)return toast('Data sudah berubah. Perbarui dashboard.');if(x.canOpen){document.querySelector('#modal')?.close();if(kind==='correction')return go('Persetujuan');return go(({task:'Aktivitas detail',lead:'Lead detail',customer:'Nasabah detail',opp:'Opportunity detail'})[kind],id)}rdModal('Monitoring · '+x.name,'<p class="rd-readonly">Tampilan baca dari kantor di bawah pengawasan. Perubahan dilakukan oleh tim kantor penempatan data.</p><dl class="rd-detail">'+[['ID',x.id],['Kantor',x.branch],['AO',x.owner||'Belum ditetapkan'],['Status / tahap',x.stage||'—'],['Produk',x.product||'—'],['Nominal pipeline',kind==='opp'?rup(x.value):'—'],['Jadwal',x.scheduled?fmt(x.scheduled):'—'],['Deadline',x.due?fmt(x.due):'—']].map(([k,v])=>'<div><dt>'+E(k)+'</dt><dd>'+E(v)+'</dd></div>').join('')+'</dl>')}
function rdList(key){const d=rdData();if(!d)return;const names={tasks:'Semua Task',today:'Task hari ini',overdue:'Task overdue',leads:'Leads',customers:'Customer 360',opps:'Opportunity',active:'Opportunity aktif',leadSla:'SLA Lead terlewat',oppSla:'SLA Opportunity terlewat',noNext:'Opportunity tanpa Task berikutnya',approvals:'Persetujuan kunjungan',corrections:'Koreksi data',escalations:'Eskalasi SLA'};let rows=d.records[key]||[];rdModal(names[key]||'Rincian', '<p class="rd-readonly">'+rows.length+' record · '+E(d.branches.join(' · '))+'</p><div class="rd-records">'+(rows.map(rdRecord).join('')||'<p class="rd-empty">Tidak ada record pada filter ini.</p>')+'</div>')}
function rdRecord(x){return '<button type="button" class="rd-record" onclick="'+rdCall('rdOpen',x.kind,x.id)+'"><span><strong>'+E(x.name||x.id)+'</strong><small>'+E([x.owner,x.product||x.branch].filter(Boolean).join(' · '))+'</small></span><span><b>'+E(x.escalationTitle||x.stage||'—')+'</b><small>'+E(x.kind==='opp'?rdMoney(x.value):x.scheduled?fmt(x.scheduled):x.branch)+'</small></span></button>'}
function rdMetric(label,value,note,key){return '<button class="rd-metric'+(String(value).startsWith('Rp')?' rd-money':'')+'" onclick="'+rdCall('rdList',key)+'"><span>'+E(label)+'</span><strong>'+E(value)+'</strong><small>'+E(note)+'</small></button>'}
function rdPanel(title,note,body,action=''){return '<section class="rd-panel"><div class="rd-panel-head"><div><h2>'+E(title)+'</h2><p>'+E(note)+'</p></div>'+action+'</div>'+body+'</section>'}
function rdQueues(d,keys){const names={today:'Hari ini',overdue:'Overdue',approvals:'Persetujuan',corrections:'Koreksi data',escalations:'Eskalasi',leadSla:'SLA Lead',oppSla:'SLA Opportunity',noNext:'Tanpa Task lanjutan'};const selected=keys.includes(roleDashQueue)?roleDashQueue:keys[0],rows=d.records[selected]||[];return rdPanel(authUser.role==='SPV'?'Pusat tindak lanjut tim':'Prioritas pekerjaan','Klik record untuk membuka detail. Data Capem ditampilkan sebagai monitoring baca.','<div class="rd-tabs">'+keys.map(k=>'<button aria-pressed="'+(selected===k)+'" class="'+(selected===k?'active':'')+'" onclick="'+rdCall('rdQueue',k)+'">'+names[k]+' <b>'+d.records[k].length+'</b></button>').join('')+'</div><div class="rd-records">'+(rows.slice(0,5).map(rdRecord).join('')||'<div class="rd-empty">Tidak ada '+E(names[selected].toLowerCase())+' pada cakupan ini.</div>')+'</div><button class="rd-more" onclick="'+rdCall('rdList',selected)+'">Lihat semua ('+rows.length+')</button>')}
function rdTargets(d){const s=d.summary;return rdPanel('Target & realisasi','Bulan '+d.period+' · hanya nominal Won dengan konfirmasi realisasi.','<div class="rd-targets">'+[['Kredit','credit','targetCredit'],['Dana','funding','targetFunding']].map(([label,actual,target])=>{const pct=s[target]?Math.round(s[actual]/s[target]*100):null;return '<div><span>'+label+'<b>'+E(pct===null?'Belum ada target':pct+'%')+'</b></span><strong>'+E(rdMoney(s[actual]))+'</strong><small>Target '+E(s[target]?rdMoney(s[target]):'belum ditetapkan')+'</small><div class="rd-track"><i style="width:'+Math.min(100,pct||0)+'%"></i></div></div>'}).join('')+'</div><p class="rd-note">'+d.unconfirmedWon.length+' Won belum memiliki konfirmasi realisasi lengkap.</p>', '<button onclick="rdGo(\'Target & Kinerja\')">'+(authUser.role==='Kepala Kantor'?'Atur target kantor':'Rincian target')+'</button>')}
function rdPipeline(d){const max=Math.max(1,...d.stages.map(s=>s.value));return rdPanel('Distribusi pipeline aktif','Nominal indikatif per tahap saat ini; terpisah dari realisasi.','<div class="rd-stages">'+d.stages.map(s=>'<button onclick="'+rdCall('rdStage',s.id)+'"><span><b>'+E(s.name)+'</b><strong>'+E(rdMoney(s.value))+'</strong></span><div class="rd-track"><i style="width:'+(s.value/max*100)+'%"></i></div><small>'+s.count+' opportunity</small></button>').join('')+'</div>')}
function rdStage(id){const d=rdData();if(!d)return;const stage=d.stages.find(s=>s.id===id);rdModal('Pipeline · '+stage.name,'<div class="rd-records">'+(d.records.opps.filter(o=>o.outcome==='Aktif'&&o.stage===stage.name).map(rdRecord).join('')||'<p class="rd-empty">Belum ada Opportunity pada tahap ini.</p>')+'</div>')}
function rdOfficeRows(d){return rdPanel('Perbandingan kantor','Setiap baris hanya menghitung kantor tersebut; Capem tidak dihitung ulang di kantor induk.','<div class="rd-office-list">'+d.rows.filter(r=>r.branch!==BPD_BRANCH_NAMES[0]).map(r=>'<button class="rd-office-row" onclick="'+rdCall('rdFilter','office',r.branch)+'"><span><strong>'+E(r.branch)+'</strong><small>'+E(d.offices.find(o=>o.name===r.branch)?.parent===BPD_BRANCH_NAMES[0]?'Kantor cabang':'Di bawah '+r.parent)+' · '+r.aoCount+' AO</small></span><span><b>'+E(rdMoney(r.pipeline))+'</b><small>'+r.active+' opportunity aktif</small></span><span><b>'+r.overdue+'</b><small>Task overdue</small></span><span><b>'+E(rdMoney(r.credit+r.funding))+'</b><small>Realisasi '+E(d.period)+'</small></span></button>').join('')+'</div>',roleDashOffice?'<button onclick="rdReset()">Semua kantor dalam akses</button>':'')}
function rdTeam(d){return rdPanel('Kinerja & beban kerja AO','Klik AO untuk menyaring seluruh dashboard. Angka bisnis mengikuti bulan terpilih.','<div class="rd-team-list">'+(d.aoRows.filter(r=>!roleDashOwner||r.id===roleDashOwner).map(r=>'<button class="rd-team-row" onclick="'+rdCall('rdFilter','owner',r.id)+'"><span><strong>'+E(r.name)+'</strong><small>'+E(r.branch)+'</small></span><span><b>'+r.active+'</b><small>Opportunity aktif</small></span><span><b>'+r.openTasks+'</b><small>Task terbuka</small></span><span class="'+(r.overdue?'rd-warning':'')+'"><b>'+r.overdue+'</b><small>Overdue</small></span></button>').join('')||'<p class="rd-empty">Belum ada AO pada kantor ini.</p>')+'</div>')}
function rdHierarchy(d){const root=d.offices.find(o=>!o.parent),branches=d.offices.filter(o=>o.parent===BPD_BRANCH_NAMES[0]);return '<div class="rd-hierarchy">'+(root?'<strong>'+E(root.name)+'</strong>':'')+branches.map(o=>'<div><b>'+E(o.name)+'</b>'+d.offices.filter(c=>c.parent===o.name).map(c=>'<span>'+E(c.name)+'</span>').join('')+'</div>').join('')+'</div>'}
function rdAdmin(d){const a=d.administration;return '<div class="rd-metrics">'+[['Member aktif',a.activeMembers,'Member'],['Member nonaktif',a.inactiveMembers,'Member'],['Kantor terdaftar',d.allowedBranches.length,'Member'],['Temuan konsistensi',a.checks.errors.length,'Kesiapan POC']].map(([label,n,route])=>'<button class="rd-metric" onclick="'+rdCall('rdGo',route)+'"><span>'+label+'</span><strong>'+n+'</strong><small>'+E(route==='Member'?'Kelola akun dari HQ Renon':'Lihat hasil pemeriksaan')+'</small></button>').join('')+'</div>'+rdPanel('Struktur kantor & akses','Satu kantor penempatan per akun. Pusat memonitor seluruh kantor; cabang memonitor Capem di bawahnya.',rdHierarchy(d)+'<div class="rd-admin-actions"><button onclick="rdGo(\'Member\')">Kelola Member</button><button onclick="rdGo(\'Pengaturan\')">Master & aturan SLA</button><button onclick="rdGo(\'Kesiapan POC\')">Periksa kesiapan POC</button></div>')+rdPanel('Kualitas data & akun','Pemeriksaan otomatis terhadap data CRM, bukan hasil integrasi Bank.','<div class="rd-health"><p><b>'+a.unassigned+'</b> akun aktif tidak memiliki tepat satu kantor penempatan.</p><p><b>'+a.checks.errors.length+'</b> kesalahan relasi / status data.</p><p><b>'+a.checks.warnings.length+'</b> catatan pemeriksaan.</p></div>')}
function roleDashboardScreen(){rdContext();const role=authUser?.role||'AO',entry=roleDashCache.get(rdKey()),d=entry?.data;
 const copy={AO:['Pekerjaan saya','Tindak lanjuti relasi, penuhi SLA, dan gerakkan peluang Anda.'],SPV:['Kendali tim & persetujuan','Tinjau keputusan, eskalasi, dan pembagian pekerjaan tim.'],'Kepala Kantor':['Kinerja kantor','Pantau pencapaian kantor, kapasitas AO, dan hambatan bisnis.'],'Manajemen Pusat':['Kinerja jaringan kantor','Bandingkan pencapaian cabang dan Capem, lalu telusuri ke AO.'],Superadmin:['Administrasi CRM','Kelola akun, struktur kantor, konfigurasi, dan kualitas data.']}[role]||['Monitoring','Ringkasan CRM'];
 let html='<div class="role-dashboard" data-dashboard-role="'+E(role)+'"><header class="rd-heading"><div><small>'+E(role.toUpperCase())+' · '+E(activeBranch)+'</small><h1>'+copy[0]+'</h1><p>'+copy[1]+'</p></div><div class="rd-heading-actions">'+(role==='AO'?'<button onclick="createLead()">Buat Lead</button><button class="primary" onclick="newTask()">Buat Task</button>':'')+'<button onclick="rdLoad(true)" '+(entry?.loading?'disabled':'')+'>Perbarui</button></div></header>';
 if(!d)return html+'<div class="rd-loading" role="status">'+E(entry?.error||'Memuat dashboard sesuai role Anda…')+(entry?.error?'<button onclick="rdLoad(true)">Coba lagi</button>':'')+'</div></div>';
 const s=d.summary;if(role!=='Superadmin')html+='<div class="rd-toolbar"><label>Bulan hasil<input type="month" value="'+E(roleDashPeriod)+'" onchange="rdFilter(\'period\',this.value)"></label>'+(d.allowedBranches.length>1?'<label>Kantor<select onchange="rdFilter(\'office\',this.value)"><option value="">Seluruh kantor dalam akses</option>'+d.offices.map(o=>'<option value="'+E(o.name)+'" '+(roleDashOffice===o.name?'selected':'')+'>'+E(o.name)+'</option>').join('')+'</select></label>':'')+(role!=='AO'&&role!=='Superadmin'?'<label>AO<select onchange="rdFilter(\'owner\',this.value)"><option value="">Semua AO</option>'+d.aoRows.map(r=>'<option value="'+E(r.id)+'" '+(roleDashOwner===r.id?'selected':'')+'>'+E(r.name)+' · '+E(r.branch.replace('BPD BALI ',''))+'</option>').join('')+'</select></label>':'')+((roleDashOffice||roleDashOwner)?'<button onclick="rdReset()">Reset filter</button>':'')+'<span class="rd-scope">'+d.branches.length+' kantor · snapshot aktif saat ini<br>Hasil & target: '+E(d.period)+' · WITA</span></div>';
 if(role==='Superadmin')html+=rdAdmin(d);
 else if(role==='AO')html+='<div class="rd-metrics">'+rdMetric('Task hari ini',s.today,s.todayDone+' selesai · '+s.todayCancelled+' dibatalkan','today')+rdMetric('Task overdue',s.overdue,'Selesaikan / jadwalkan ulang','overdue')+rdMetric('SLA Lead terlewat',s.leadSla,'Respons dan kualifikasi','leadSla')+rdMetric('Opportunity aktif',s.active,rdMoney(s.pipeline)+' nominal pipeline','active')+'</div>'+rdQueues(d,['today','overdue','leadSla','noNext'])+'<div class="rd-grid">'+rdTargets(d)+rdPipeline(d)+'</div>';
 else if(role==='SPV')html+='<div class="rd-metrics">'+rdMetric('Menunggu persetujuan',s.approvals,'Rencana / perubahan kunjungan','approvals')+rdMetric('Koreksi data',s.corrections,'Permintaan yang perlu keputusan','corrections')+rdMetric('Eskalasi SLA',s.escalations,'Kantor dan Capem dalam pengawasan','escalations')+rdMetric('Task overdue',s.overdue,'Beban kerja tim saat ini','overdue')+'</div>'+rdQueues(d,['approvals','corrections','escalations','overdue','leadSla'])+rdTeam(d)+(d.allowedBranches.length>1?rdOfficeRows(d):'');
 else html+='<div class="rd-metrics">'+rdMetric('Pipeline aktif',rdMoney(s.pipeline),s.active+' opportunity','active')+rdMetric('Customer',s.customers,'Customer dalam cakupan monitoring','customers')+rdMetric('SLA Lead terlewat',s.leadSla,'Perlu tindak lanjut tim','leadSla')+rdMetric('Task overdue',s.overdue,'Hambatan pekerjaan tim','overdue')+'</div>'+rdTargets(d)+(d.allowedBranches.length>1?rdOfficeRows(d):'')+'<div class="rd-grid">'+rdPipeline(d)+rdPanel('Hasil penutupan Opportunity','Berdasarkan tanggal penutupan pada bulan terpilih.','<div class="rd-outcomes"><div><strong>'+s.won+'</strong><span>Won</span></div><div><strong>'+s.lost+'</strong><span>Lost</span></div><div><strong>'+(s.won+s.lost?Math.round(s.won/(s.won+s.lost)*100)+'%':'—')+'</strong><span>Win rate</span></div></div><p class="rd-note">Won ÷ (Won + Lost). Cancelled tidak masuk perhitungan. Nominal Won belum tentu realisasi.</p>')+'</div>'+rdTeam(d);
 return html+'<footer class="rd-footer">Data dummy POC · sesuai hak akses · diperbarui '+E(fmt(d.at))+' WITA</footer></div>';
}
const roleDashboardPrevious=renderContent;
renderContent=function(){roleDashboardPrevious();if(!authUser||choosingBranch||journey||!['Monitoring','Home'].includes(view))return;const app=document.querySelector('#app');if(!app)return;const screen=roleDashboardScreen();if(mobile&&view==='Home'){const menus=app.querySelector('.homemenus')?.outerHTML||'';app.innerHTML=(typeof homeAttendanceHero==='function'?homeAttendanceHero():'')+screen+'<h2 class="rd-workspace-title">Menu workspace</h2>'+menus;}else if(view==='Monitoring')app.innerHTML=screen;rdLoad();};
if(typeof authUser!=='undefined'&&authUser&&!choosingBranch)renderContent();
